B.bzG={"\u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u0642\u0645\u0631":0,"\u0645\u0624\u0634\u0631 UV":1,"\u0627\u0644\u0634\u0639\u0648\u0631":2,"\u0627\u0644\u0631\u064a\u0627\u062d":3,"\u0627\u0644\u0634\u0631\u0648\u0642 \u0648\u0627\u0644\u063a\u0631\u0648\u0628":4,"\u0627\u0644\u0631\u0637\u0648\u0628\u0629":5,"\u0627\u0644\u0631\u0624\u064a\u0629":6,"\u0627\u0644\u0636\u063a\u0637":7,"\u062c\u0648\u062f\u0629 \u0627\u0644\u0647\u0648\u0627\u0621":8,"\u0627\u0644\u062a\u0647\u0627\u0628 \u0627\u0644\u0645\u0641\u0627\u0635\u0644":9,"\u0636\u063a\u0637 \u0627\u0644\u062c\u064a\u0648\u0628":10,"\u0627\u0644\u0628\u0631\u062f \u0648\u0627\u0644\u0625\u0646\u0641\u0644\u0648\u0646\u0632\u0627":11,"\u0627\u0644\u0635\u062f\u0627\u0639 \u0627\u0644\u0646\u0635\u0641\u064a":12,"\u0627\u0644\u0631\u0628\u0648":13,"\u0627\u0644\u0628\u0639\u0648\u0636":14}
B.bcl=new A.a1(B.bzG,[u.cS,u.aP,u.m,u.G,u.bl,"  \u062a\u0639\u062a\u0628\u0631 \u0627\u0644\u0631\u0637\u0648\u0628\u0629 \u0627\u0644\u062c\u0648\u064a\u0629 \u0645\u0646 \u0623\u0647\u0645 \u0639\u0646\u0627\u0635\u0631 \u0627\u0644\u0637\u0642\u0633 \u0627\u0644\u062a\u064a \u062a\u0624\u062b\u0631 \u0628\u0634\u0643\u0644 \u0645\u0628\u0627\u0634\u0631 \u0639\u0644\u0649 \u0631\u0627\u062d\u0629 \u0627\u0644\u0625\u0646\u0633\u0627\u0646 \u0648\u0635\u062d\u062a\u0647\u060c \u062e\u0627\u0635\u0629 \u0639\u0646\u062f \u0627\u0631\u062a\u0641\u0627\u0639 \u062f\u0631\u062c\u0627\u062a \u0627\u0644\u062d\u0631\u0627\u0631\u0629. \u0627\u0644\u0631\u0637\u0648\u0628\u0629 \u0647\u064a \u0643\u0645\u064a\u0629 \u0628\u062e\u0627\u0631 \u0627\u0644\u0645\u0627\u0621 \u0627\u0644\u0645\u0648\u062c\u0648\u062f\u0629 \u0641\u064a \u0627\u0644\u0647\u0648\u0627\u0621\u060c \u0648\u0642\u064a\u0627\u0633\u0647\u0627 \u064a\u0639\u062f \u0645\u0624\u0634\u0631\u0627\u064b \u0647\u0627\u0645\u0627\u064b \u0644\u0644\u062a\u0646\u0628\u0624 \u0628\u0627\u0644\u0637\u0642\u0633 \u0648\u0634\u0639\u0648\u0631\u0646\u0627 \u0628\u0627\u0644\u062d\u0631\u0627\u0631\u0629.\n\n\n  \u0641\u064a\u0645\u0627 \u064a\u0644\u064a \u062a\u0641\u0635\u064a\u0644 \u0644\u0645\u0639\u062f\u0644\u0627\u062a \u0627\u0644\u0631\u0637\u0648\u0628\u0629 \u0627\u0644\u062c\u0648\u064a\u0629 \u0648\u0646\u0635\u0627\u0626\u062d \u0644\u0644\u062a\u0639\u0627\u0645\u0644 \u0645\u0639\u0647\u0627 \u0641\u064a \u0627\u0644\u062d\u064a\u0627\u0629 \u0627\u0644\u064a\u0648\u0645\u064a\u0629:\n\n  \u0623\u0648\u0644\u0627\u064b: \u0645\u0639\u062f\u0644\u0627\u062a \u0627\u0644\u0631\u0637\u0648\u0628\u0629 \u0627\u0644\u062c\u0648\u064a\u0629 (\u0627\u0644\u0645\u062b\u0627\u0644\u064a\u0629 \u0648\u0627\u0644\u0645\u0631\u062a\u0641\u0639\u0629)\n  \u0627\u0644\u0631\u0637\u0648\u0628\u0629 \u0627\u0644\u0645\u062b\u0627\u0644\u064a\u0629 (\u0627\u0644\u0645\u0631\u064a\u062d\u0629): \u062a\u062a\u0631\u0627\u0648\u062d \u0646\u0633\u0628\u0629 \u0627\u0644\u0631\u0637\u0648\u0628\u0629 \u0627\u0644\u0645\u0631\u064a\u062d\u0629 \u0644\u0644\u0625\u0646\u0633\u0627\u0646 \u062f\u0627\u062e\u0644 \u0627\u0644\u0645\u0646\u0632\u0644 \u0648\u062e\u0627\u0631\u062c\u0647 \u0628\u064a\u0646 40% \u0648 60%.\n  \u0627\u0644\u0631\u0637\u0648\u0628\u0629 \u0627\u0644\u0639\u0627\u0644\u064a\u0629 (\u063a\u064a\u0631 \u0627\u0644\u0645\u0631\u064a\u062d\u0629): \u0639\u0646\u062f\u0645\u0627 \u062a\u062a\u062c\u0627\u0648\u0632 \u0627\u0644\u0631\u0637\u0648\u0628\u0629 60% - 70%\u060c \u064a\u0628\u062f\u0623 \u0627\u0644\u0625\u0646\u0633\u0627\u0646 \u0628\u0627\u0644\u0634\u0639\u0648\u0631 \u0628\u0639\u062f\u0645 \u0627\u0644\u0631\u0627\u062d\u0629\u060c \u0627\u0644\u062e\u0645\u0648\u0644\u060c \u0648\u0636\u064a\u0642 \u0627\u0644\u062a\u0646\u0641\u0633\u060c \u062d\u064a\u062b \u064a\u0639\u062c\u0632 \u0627\u0644\u062c\u0633\u0645 \u0639\u0646 \u062a\u0628\u0631\u064a\u062f \u0646\u0641\u0633\u0647 \u0639\u0628\u0631 \u0627\u0644\u062a\u0639\u0631\u0642.\n  \u0627\u0644\u0631\u0637\u0648\u0628\u0629 \u0627\u0644\u0645\u0646\u062e\u0641\u0636\u0629: \u0623\u0642\u0644 \u0645\u0646 30%\u060c \u0648\u062a\u0633\u0628\u0628 \u062c\u0641\u0627\u0641 \u0627\u0644\u062c\u0644\u062f \u0648\u0627\u0644\u062c\u0647\u0627\u0632 \u0627\u0644\u062a\u0646\u0641\u0633\u064a.\n\n\n  \u062b\u0627\u0646\u064a\u0627\u064b: \u062a\u0623\u062b\u064a\u0631 \u0627\u0644\u0631\u0637\u0648\u0628\u0629 \u0627\u0644\u0639\u0627\u0644\u064a\u0629 \u0639\u0644\u0649 \u0627\u0644\u0635\u062d\u0629\n  \u0632\u064a\u0627\u062f\u0629 \u0627\u0644\u0634\u0639\u0648\u0631 \u0628\u0627\u0644\u062d\u0631\u0627\u0631\u0629: \u0627\u0644\u0631\u0637\u0648\u0628\u0629 \u0627\u0644\u0639\u0627\u0644\u064a\u0629 \u062a\u0645\u0646\u0639 \u062a\u0628\u062e\u0631 \u0627\u0644\u0639\u0631\u0642 \u0639\u0646 \u0627\u0644\u062c\u0644\u062f\u060c \u0645\u0645\u0627 \u064a\u062c\u0639\u0644 \u0627\u0644\u062c\u0633\u0645 \u064a\u0634\u0639\u0631 \u0628\u062f\u0631\u062c\u0629 \u062d\u0631\u0627\u0631\u0629 \u0623\u0639\u0644\u0649 \u0628\u0643\u062b\u064a\u0631 \u0645\u0646 \u0627\u0644\u062d\u0631\u0627\u0631\u0629 \u0627\u0644\u0641\u0639\u0644\u064a\u0629.\n  \u062e\u0637\u0631 \u0627\u0644\u0625\u0635\u0627\u0628\u0629 \u0628\u0627\u0644\u062c\u0641\u0627\u0641: \u0646\u062a\u064a\u062c\u0629 \u0632\u064a\u0627\u062f\u0629 \u0627\u0644\u062a\u0639\u0631\u0642 \u0648\u0641\u0642\u062f\u0627\u0646 \u0627\u0644\u0633\u0648\u0627\u0626\u0644.\n  \u0627\u0644\u062a\u0623\u062b\u064a\u0631\u0627\u062a \u0627\u0644\u0646\u0641\u0633\u064a\u0629: \u0627\u0644\u062a\u0648\u062a\u0631\u060c \u0627\u0644\u0642\u0644\u0642\u060c \u0635\u0639\u0648\u0628\u0629 \u0627\u0644\u062a\u0631\u0643\u064a\u0632\u060c \u0648\u0627\u0646\u062e\u0641\u0627\u0636 \u0627\u0644\u0637\u0627\u0642\u0629.\n  \u0645\u0634\u0627\u0643\u0644 \u0635\u062d\u064a\u0629: \u0642\u062f \u062a\u0633\u0628\u0628 \u0645\u0634\u0627\u0643\u0644 \u0644\u0645\u0631\u0636\u0649 \u0627\u0644\u062c\u0647\u0627\u0632 \u0627\u0644\u062a\u0646\u0641\u0633\u064a \u0648\u0627\u0644\u0631\u0628\u0648.\n\n\n  \u062b\u0627\u0644\u062b\u0627\u064b: \u0646\u0635\u0627\u0626\u062d \u0644\u0644\u062d\u064a\u0627\u0629 \u0627\u0644\u064a\u0648\u0645\u064a\u0629 \u0641\u064a \u0627\u0644\u0637\u0642\u0633 \u0627\u0644\u0631\u0637\u0628\n  \u0627\u0644\u062a\u0631\u0637\u064a\u0628 \u0627\u0644\u062f\u0627\u062e\u0644\u064a: \u0634\u0631\u0628 \u0643\u0645\u064a\u0627\u062a \u0643\u0628\u064a\u0631\u0629 \u0645\u0646 \u0627\u0644\u0645\u0627\u0621 \u0648\u0627\u0644\u0633\u0648\u0627\u0626\u0644 (\u062d\u062a\u0649 \u062f\u0648\u0646 \u0627\u0644\u0634\u0639\u0648\u0631 \u0628\u0627\u0644\u0639\u0637\u0634) \u0644\u062a\u0639\u0648\u064a\u0636 \u0627\u0644\u0633\u0648\u0627\u0626\u0644 \u0627\u0644\u0645\u0641\u0642\u0648\u062f\u0629.\n\n  \u0627\u0644\u0645\u0644\u0627\u0628\u0633 \u0627\u0644\u0645\u0646\u0627\u0633\u0628\u0629: \u0627\u0631\u062a\u062f\u0627\u0621 \u0645\u0644\u0627\u0628\u0633 \u062e\u0641\u064a\u0641\u0629\u060c \u0641\u0636\u0641\u0627\u0636\u0629\u060c \u0648\u0630\u0627\u062a \u0623\u0644\u0648\u0627\u0646 \u0641\u0627\u062a\u062d\u0629 (\u064a\u0641\u0636\u0644 \u0627\u0644\u0642\u0637\u0646) \u0644\u062a\u0633\u0645\u062d \u0628\u062a\u0628\u062e\u0631 \u0627\u0644\u0639\u0631\u0642 \u0648\u062a\u0628\u0631\u064a\u062f \u0627\u0644\u062c\u0633\u0645.\n\n  \u062a\u0639\u062f\u064a\u0644 \u0627\u0644\u0646\u0634\u0627\u0637 \u0627\u0644\u0628\u062f\u0646\u064a: \u062a\u062c\u0646\u0628 \u0645\u0645\u0627\u0631\u0633\u0629 \u0627\u0644\u0631\u064a\u0627\u0636\u0629 \u0623\u0648 \u0627\u0644\u0645\u062c\u0647\u0648\u062f \u0627\u0644\u0628\u062f\u0646\u064a \u0627\u0644\u0634\u0627\u0642 \u0641\u064a \u0633\u0627\u0639\u0627\u062a \u0627\u0644\u0630\u0631\u0648\u0629 (\u0645\u0646 10 \u0635\u0628\u0627\u062d\u0627\u064b \u0625\u0644\u0649 4 \u0639\u0635\u0631\u0627\u064b).\n\n  \u0627\u0644\u062a\u0647\u0648\u064a\u0629 \u0627\u0644\u0630\u0643\u064a\u0629: \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0623\u062c\u0647\u0632\u0629 \u0627\u0644\u062a\u0643\u064a\u064a\u0641 (\u0627\u0644\u0645\u0643\u064a\u0641\u0627\u062a \u062a\u0642\u0648\u0645 \u0628\u062a\u0642\u0644\u064a\u0644 \u0627\u0644\u0631\u0637\u0648\u0628\u0629) \u0623\u0648 \u0627\u0644\u0645\u0631\u0627\u0648\u062d \u0644\u062a\u0644\u0637\u064a\u0641 \u0627\u0644\u062c\u0648. \u064a\u0641\u0636\u0644 \u0625\u063a\u0644\u0627\u0642 \u0627\u0644\u0646\u0648\u0627\u0641\u0630 \u062e\u0644\u0627\u0644 \u0627\u0644\u0646\u0647\u0627\u0631 \u0648\u0645\u0646\u0639 \u062f\u062e\u0648\u0644 \u0627\u0644\u0647\u0648\u0627\u0621 \u0627\u0644\u0631\u0637\u0628.\n\n  \u0627\u0644\u0639\u0646\u0627\u064a\u0629 \u062f\u0627\u062e\u0644 \u0627\u0644\u0645\u0646\u0632\u0644: \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0645\u0632\u064a\u0644\u0627\u062a \u0627\u0644\u0631\u0637\u0648\u0628\u0629 (Dehumidifiers) \u0625\u0630\u0627 \u0644\u0632\u0645 \u0627\u0644\u0623\u0645\u0631\u060c \u0648\u062a\u0641\u0642\u062f \u0627\u0644\u0645\u0646\u0632\u0644 \u0628\u062d\u062b\u0627\u064b \u0639\u0646 \u0639\u0644\u0627\u0645\u0627\u062a \u0627\u0644\u0639\u0641\u0646 \u0627\u0644\u0646\u0627\u062a\u062c\u0629 \u0639\u0646 \u0627\u0644\u0631\u0637\u0648\u0628\u0629 \u0627\u0644\u0632\u0627\u0626\u062f\u0629.\n\n  \u0627\u0644\u062a\u062f\u0631\u062c \u0641\u064a \u062f\u0631\u062c\u0627\u062a \u0627\u0644\u062d\u0631\u0627\u0631\u0629: \u062a\u062c\u0646\u0628 \u0627\u0644\u0627\u0646\u062a\u0642\u0627\u0644 \u0627\u0644\u0645\u0641\u0627\u062c\u0626 \u0645\u0646 \u0623\u0645\u0627\u0643\u0646 \u0645\u0643\u064a\u0641\u0629 \u0628\u0634\u062f\u0629 \u0625\u0644\u0649 \u0627\u0644\u062d\u0631\u0627\u0631\u0629 \u0648\u0627\u0644\u0631\u0637\u0648\u0628\u0629 \u0627\u0644\u0639\u0627\u0644\u064a\u0629 \u0641\u064a \u0627\u0644\u062e\u0627\u0631\u062c \u0644\u062a\u062c\u0646\u0628 \u0627\u0644\u0635\u062f\u0645\u0629 \u0627\u0644\u062d\u0631\u0627\u0631\u064a\u0629.\n\n  \u0627\u0644\u0627\u0633\u062a\u062d\u0645\u0627\u0645 \u0628\u0645\u0627\u0621 \u0641\u0627\u062a\u0631: \u064a\u0633\u0627\u0639\u062f \u0641\u064a \u062a\u0642\u0644\u064a\u0644 \u062f\u0631\u062c\u0629 \u062d\u0631\u0627\u0631\u0629 \u0627\u0644\u062c\u0633\u0645.\n\n\n  \u0628\u0627\u062a\u0628\u0627\u0639 \u0647\u0630\u0647 \u0627\u0644\u0646\u0635\u0627\u0626\u062d\u060c \u064a\u0645\u0643\u0646 \u062a\u0642\u0644\u064a\u0644 \u0627\u0644\u062a\u0623\u062b\u064a\u0631\u0627\u062a \u0627\u0644\u0633\u0644\u0628\u064a\u0629 \u0644\u0644\u0631\u0637\u0648\u0628\u0629 \u0648\u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0644\u0635\u062d\u0629 \u0648\u0627\u0644\u0646\u0634\u0627\u0637 \u062e\u0644\u0627\u0644 \u0627\u0644\u0623\u064a\u0627\u0645 \u0627\u0644\u062d\u0627\u0631\u0629 \u0648\u0627\u0644\u0631\u0637\u0628\u0629.\n\n","  \u064a\u0639\u062f \u0645\u062f\u0649 \u0627\u0644\u0631\u0624\u064a\u0629 \u0627\u0644\u0623\u0641\u0642\u064a\u0629 \u0639\u0646\u0635\u0631\u0627\u064b \u062d\u064a\u0648\u064a\u0627\u064b \u0641\u064a \u0646\u0634\u0631\u0627\u062a \u0627\u0644\u0623\u0631\u0635\u0627\u062f \u0627\u0644\u062c\u0648\u064a\u0629\u060c \u062d\u064a\u062b \u064a\u0642\u064a\u0633 \u0627\u0644\u0645\u0633\u0627\u0641\u0629 \u0627\u0644\u062a\u064a \u064a\u0645\u0643\u0646 \u0644\u0644\u0639\u064a\u0646 \u062a\u0645\u064a\u064a\u0632 \u0627\u0644\u0623\u062c\u0633\u0627\u0645 \u062e\u0644\u0627\u0644\u0647\u0627 \u0628\u0648\u0636\u0648\u062d\u060c \u0648\u064a\u062a\u0623\u062b\u0631 \u0628\u0634\u0643\u0644 \u0645\u0628\u0627\u0634\u0631 \u0628\u0638\u0648\u0627\u0647\u0631 \u0645\u062b\u0644 \u0627\u0644\u0636\u0628\u0627\u0628\u060c \u0627\u0644\u063a\u0628\u0627\u0631\u060c \u0648\u0627\u0644\u0623\u0645\u0637\u0627\u0631.\n\n\n  \u0645\u0639\u062f\u0644\u0627\u062a \u0627\u0644\u0631\u0624\u064a\u0629 \u0648\u062a\u0635\u0646\u064a\u0641\u0627\u062a\u0647\u0627:\n  \n  \u0631\u0624\u064a\u0629 \u0645\u0645\u062a\u0627\u0632\u0629/\u062c\u064a\u062f\u0629:\n  \u062a\u0632\u064a\u062f \u0639\u0646 10 \u0643\u064a\u0644\u0648\u0645\u062a\u0631\u0627\u062a\u060c \u062d\u064a\u062b \u062a\u0643\u0648\u0646 \u0627\u0644\u0631\u0624\u064a\u0629 \u0648\u0627\u0636\u062d\u0629 \u062a\u0645\u0627\u0645\u0627\u064b.\n  \n  \u0631\u0624\u064a\u0629 \u0645\u062a\u0648\u0633\u0637\u0629:\n   \u062a\u062a\u0631\u0627\u0648\u062d \u0639\u0627\u062f\u0629 \u0628\u064a\u0646 5 \u0625\u0644\u0649 10 \u0643\u064a\u0644\u0648\u0645\u062a\u0631\u0627\u062a.\n   \n  \u0631\u0624\u064a\u0629 \u0636\u0639\u064a\u0641\u0629/\u0645\u0646\u062e\u0641\u0636\u0629:\n   \u0623\u0642\u0644 \u0645\u0646 5 \u0643\u064a\u0644\u0648\u0645\u062a\u0631\u0627\u062a (\u0642\u062f \u062a\u0628\u062f\u0623 \u0645\u0646 3 \u0643\u0645)\u060c \u0648\u062a\u0624\u062b\u0631 \u0639\u0644\u0649 \u062d\u0631\u0643\u0629 \u0627\u0644\u0645\u0631\u0648\u0631 \u0648\u0627\u0644\u0637\u064a\u0631\u0627\u0646.\n   \n  \u0627\u0646\u0639\u062f\u0627\u0645 \u0627\u0644\u0631\u0624\u064a\u0629:\n   \u0623\u0642\u0644 \u0645\u0646 1000 \u0645\u062a\u0631 (1 \u0643\u0645) \u0623\u0648 \u0623\u0642\u0644\u060c \u0648\u062a\u062d\u062f\u062b \u0641\u064a \u0627\u0644\u0636\u0628\u0627\u0628 \u0627\u0644\u0643\u062b\u064a\u0641 \u0623\u0648 \u0627\u0644\u0639\u0648\u0627\u0635\u0641 \u0627\u0644\u062a\u0631\u0627\u0628\u064a\u0629 \u0627\u0644\u0634\u062f\u064a\u062f\u0629.\n\n\n  \u0646\u0635\u0627\u0626\u062d \u0644\u0644\u062d\u064a\u0627\u0629 \u0627\u0644\u064a\u0648\u0645\u064a\u0629 \u0623\u062b\u0646\u0627\u0621 \u062a\u062f\u0646\u064a \u0627\u0644\u0631\u0624\u064a\u0629 \u0648\u0627\u0644\u0637\u0642\u0633 \u0627\u0644\u0633\u064a\u0626:\n  \n  \u0627\u0644\u0642\u064a\u0627\u062f\u0629 \u0627\u0644\u0622\u0645\u0646\u0629:\n   \u0627\u0644\u0642\u064a\u0627\u062f\u0629 \u0628\u0647\u062f\u0648\u0621 \u0648\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u0623\u0636\u0648\u0627\u0621 \u0627\u0644\u0645\u0646\u062e\u0641\u0636\u0629 (\u0623\u0648 \u0627\u0644\u0643\u0634\u0627\u0641\u0627\u062a \u0627\u0644\u0636\u0628\u0627\u0628\u064a\u0629)\u060c \u0648\u0632\u064a\u0627\u062f\u0629 \u0645\u0633\u0627\u0641\u0629 \u0627\u0644\u0623\u0645\u0627\u0646 \u0628\u064a\u0646 \u0627\u0644\u0633\u064a\u0627\u0631\u0627\u062a.\n    \u062a\u062c\u0646\u0628 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u0623\u0636\u0648\u0627\u0621 \u0627\u0644\u0639\u0627\u0644\u064a\u0629 \u0644\u0623\u0646\u0647\u0627 \u062a\u0639\u0643\u0633 \u0627\u0644\u0636\u0648\u0621 \u0641\u064a \u0627\u0644\u0636\u0628\u0627\u0628 \u0648\u062a\u0642\u0644\u0644 \u0627\u0644\u0631\u0624\u064a\u0629.\n    \n  \u0645\u0631\u0636\u0649 \u0627\u0644\u062d\u0633\u0627\u0633\u064a\u0629 \u0648\u0627\u0644\u062c\u064a\u0648\u0628 \u0627\u0644\u0623\u0646\u0641\u064a\u0629:\n   \u062a\u062c\u0646\u0628 \u0627\u0644\u062e\u0631\u0648\u062c \u0645\u0646 \u0627\u0644\u0645\u0646\u0632\u0644 \u062e\u0644\u0627\u0644 \u0646\u0634\u0627\u0637 \u0627\u0644\u0631\u064a\u0627\u062d \u0627\u0644\u0645\u062b\u064a\u0631\u0629 \u0644\u0644\u0623\u062a\u0631\u0628\u0629 \u0648\u0627\u0644\u063a\u0628\u0627\u0631.\n   \n  \u062a\u062c\u0646\u0628 \u0627\u0644\u0623\u0645\u0627\u0643\u0646 \u0627\u0644\u0645\u0643\u0634\u0648\u0641\u0629:\n   \u0627\u0644\u0627\u0628\u062a\u0639\u0627\u062f \u0639\u0646 \u0627\u0644\u0645\u0646\u0627\u0637\u0642 \u0627\u0644\u062a\u064a \u062a\u0643\u062b\u0631 \u0641\u064a\u0647\u0627 \u0627\u0644\u0631\u064a\u0627\u062d \u0648\u0627\u0644\u063a\u0628\u0627\u0631\u060c \u0648\u062a\u062c\u0646\u0628 \u0627\u0644\u062a\u0648\u0627\u062c\u062f \u0623\u0633\u0641\u0644 \u0644\u0648\u062d\u0627\u062a \u0627\u0644\u0625\u0639\u0644\u0627\u0646\u0627\u062a \u0623\u0648 \u0627\u0644\u0623\u0634\u062c\u0627\u0631 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0631\u064a\u0627\u062d \u0627\u0644\u0642\u0648\u064a\u0629.\n   \n  \u0627\u0644\u0645\u0644\u0627\u0628\u0633 \u0627\u0644\u0645\u0646\u0627\u0633\u0628\u0629:\n   \u0627\u0631\u062a\u062f\u0627\u0621 \u0627\u0644\u0645\u0644\u0627\u0628\u0633 \u0627\u0644\u0645\u0646\u0627\u0633\u0628\u0629 \u0644\u062f\u0631\u062c\u0627\u062a \u0627\u0644\u062d\u0631\u0627\u0631\u0629 \u0648\u0639\u062f\u0645 \u062a\u062e\u0641\u064a\u0641\u0647\u0627 \u0644\u062a\u0641\u0627\u062f\u064a \u0646\u0632\u0644\u0627\u062a \u0627\u0644\u0628\u0631\u062f\u060c \u0645\u0639 \u0645\u0631\u0627\u0639\u0627\u0629 \u0627\u0644\u0631\u064a\u0627\u062d.\n   \n  \u0627\u0644\u0648\u0642\u0627\u064a\u0629 \u0645\u0646 \u0627\u0644\u063a\u0628\u0627\u0631:\n   \u0627\u0631\u062a\u062f\u0627\u0621 \u0627\u0644\u0643\u0645\u0627\u0645\u0627\u062a \u0639\u0646\u062f \u0627\u0644\u062e\u0631\u0648\u062c \u0648\u062a\u063a\u0637\u064a\u0629 \u0627\u0644\u0639\u064a\u0646\u064a\u0646 \u0644\u062d\u0645\u0627\u064a\u062a\u0647\u0645\u0627 \u0645\u0646 \u0627\u0644\u0623\u062a\u0631\u0628\u0629.\n   \n  \u0645\u062a\u0627\u0628\u0639\u0629 \u0627\u0644\u0646\u0634\u0631\u0627\u062a:\n   \u0645\u062a\u0627\u0628\u0639\u0629 \u062a\u062d\u062f\u064a\u062b\u0627\u062a \u0627\u0644\u0637\u0642\u0633 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0645\u0631 \u0644\u062a\u0641\u0627\u062f\u064a \u0627\u0644\u062a\u0642\u0644\u0628\u0627\u062a \u0627\u0644\u0633\u0631\u064a\u0639\u0629.\n\n\n  \u062a\u0624\u062b\u0631 \u0647\u0630\u0647 \u0627\u0644\u062a\u0642\u0644\u0628\u0627\u062a \u0627\u0644\u062c\u0648\u064a\u0629 \u0639\u0644\u0649 \u062c\u0648\u0627\u0646\u0628 \u062d\u064a\u0627\u062a\u0646\u0627 \u0627\u0644\u064a\u0648\u0645\u064a\u0629 \u0645\u062b\u0644 \u0627\u0644\u0635\u062d\u0629 \u0627\u0644\u0628\u062f\u0646\u064a\u0629\u060c \u0648\u0627\u0644\u0646\u0641\u0633\u064a\u0629\u060c \u0648\u062d\u062a\u0649 \u0633\u0644\u0627\u0645\u0629 \u0627\u0644\u062a\u0646\u0642\u0644 \u0648\u0627\u0644\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u0645\u062e\u062a\u0644\u0641\u0629.\n\n","\u0627\u0644\u0636\u063a\u0637 \u0627\u0644\u062c\u0648\u064a \u0647\u0648 \u0648\u0632\u0646 \u0639\u0645\u0648\u062f \u0627\u0644\u0647\u0648\u0627\u0621 \u0627\u0644\u0648\u0627\u0642\u0639 \u0639\u0644\u0649 \u0648\u062d\u062f\u0629 \u0627\u0644\u0645\u0633\u0627\u062d\u0627\u062a\u060c \u0648\u064a\u0644\u0639\u0628 \u062f\u0648\u0631\u0627\u064b \u062d\u064a\u0648\u064a\u0627\u064b \u0641\u064a \u062a\u0634\u0643\u064a\u0644 \u0627\u0644\u0637\u0642\u0633 \u0648\u062a\u0623\u062b\u064a\u0631\u0647 \u0627\u0644\u0645\u0628\u0627\u0634\u0631 \u0639\u0644\u0649 \u0635\u062d\u0629 \u0627\u0644\u0625\u0646\u0633\u0627\u0646. \u064a\u064f\u0642\u0627\u0633 \u0627\u0644\u0636\u063a\u0637 \u0627\u0644\u062c\u0648\u064a \u063a\u0627\u0644\u0628\u0627\u064b \u0628\u0648\u062d\u062f\u0629 \u0627\u0644\u0647\u064a\u0643\u062a\u0648\u0628\u0627\u0633\u0643\u0627\u0644 (hPa)\u060c \u062d\u064a\u062b \u064a\u0639\u062a\u0628\u0631 1013.25 hPa \u0647\u0648 \u0627\u0644\u0645\u0639\u064a\u0627\u0631 \u0639\u0646\u062f \u0645\u0633\u062a\u0648\u0649 \u0633\u0637\u062d \u0627\u0644\u0628\u062d\u0631. \n\n\u0645\u0639\u0627\u064a\u064a\u0631 \u0627\u0644\u0636\u063a\u0637 \u0627\u0644\u062c\u0648\u064a (hPa):\n\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0645\u0639\u064a\u0627\u0631\u064a (\u0633\u0637\u062d \u0627\u0644\u0628\u062d\u0631):\n \u064a\u0628\u0644\u063a \u062d\u0648\u0627\u0644\u064a 1013.25 \u0647\u064a\u0643\u062a\u0648\u0628\u0627\u0633\u0643\u0627\u0644.\n\u0627\u0644\u0636\u063a\u0637 \u0627\u0644\u0645\u0631\u062a\u0641\u0639:\n \u0639\u0627\u062f\u0629 \u0645\u0627 \u064a\u0643\u0648\u0646 1020 hPa \u0623\u0648 \u0623\u0639\u0644\u0649\u060c \u0648\u064a\u0631\u062a\u0628\u0637 \u0628\u0637\u0642\u0633 \u0645\u0633\u062a\u0642\u0631 \u0648\u0635\u0627\u0641\u064d.\n\u0627\u0644\u0636\u063a\u0637 \u0627\u0644\u0645\u0646\u062e\u0641\u0636:\n \u064a\u0643\u0648\u0646 \u0623\u0642\u0644 \u0645\u0646 1000 hPa\u060c \u0648\u064a\u0631\u062a\u0628\u0637 \u0628\u0627\u0644\u063a\u064a\u0648\u0645 \u0648\u0627\u0644\u0623\u0645\u0637\u0627\u0631 (\u0625\u0630\u0627 \u0643\u0627\u0646 \u0645\u0646\u062e\u0641\u0636\u0627\u064b \u062c\u062f\u0627\u064b\u060c \u064a\u0642\u0644 \u0639\u0646 980 hPa).\n\u0627\u0644\u062a\u063a\u064a\u0631 \u0645\u0639 \u0627\u0644\u0627\u0631\u062a\u0641\u0627\u0639:\n \u064a\u0646\u062e\u0641\u0636 \u0627\u0644\u0636\u063a\u0637 \u0627\u0644\u062c\u0648\u064a \u0643\u0644\u0645\u0627 \u0632\u0627\u062f \u0627\u0644\u0627\u0631\u062a\u0641\u0627\u0639\u061b \u0641\u0639\u0644\u0649 \u0627\u0631\u062a\u0641\u0627\u0639 1500 \u0645\u062a\u0631 \u064a\u0635\u0644 \u0625\u0644\u0649 850 hPa\u060c \u0628\u064a\u0646\u0645\u0627 \u0639\u0646\u062f 5500 \u0645\u062a\u0631 \u064a\u0635\u0644 \u0625\u0644\u0649 \u062d\u0648\u0627\u0644\u064a 500 hPa. \n\n\n\u062a\u0623\u062b\u064a\u0631 \u0627\u0644\u0636\u063a\u0637 \u0627\u0644\u062c\u0648\u064a \u0639\u0644\u0649 \u0627\u0644\u0625\u0646\u0633\u0627\u0646:\n\u064a\u0624\u062b\u0631 \u0627\u0644\u0636\u063a\u0637 \u0627\u0644\u062c\u0648\u064a \u0639\u0644\u0649 \u0627\u0644\u062c\u0633\u0645 \u0628\u0634\u0643\u0644 \u0645\u0628\u0627\u0634\u0631\u060c \u062d\u064a\u062b \u062a\u0624\u062f\u064a \u0627\u0644\u062a\u063a\u064a\u0631\u0627\u062a \u0627\u0644\u0633\u0631\u064a\u0639\u0629 \u0625\u0644\u0649 \u0627\u0639\u062a\u0644\u0627\u0644\u0627\u062a \u0635\u062d\u064a\u0629 (\u0627\u0639\u062a\u0644\u0627\u0644 \u0627\u0644\u0637\u0642\u0633): \n\n\u062a\u0623\u062b\u064a\u0631\u0627\u062a \u0627\u0644\u0627\u0646\u062e\u0641\u0627\u0636 \u0627\u0644\u0634\u062f\u064a\u062f (\u0627\u0644\u0645\u0631\u062a\u0641\u0639\u0627\u062a):\n\u0646\u0642\u0635 \u0627\u0644\u0623\u0643\u0633\u062c\u064a\u0646 (Hypoxia):\n \u0643\u0644\u0645\u0627 \u0632\u0627\u062f \u0627\u0644\u0627\u0631\u062a\u0641\u0627\u0639\u060c \u0642\u0644 \u0627\u0644\u0636\u063a\u0637 \u0648\u0643\u062b\u0627\u0641\u0629 \u0627\u0644\u0647\u0648\u0627\u0621\u060c \u0645\u0645\u0627 \u064a\u0642\u0644\u0644 \u0627\u0644\u0623\u0643\u0633\u062c\u064a\u0646 \u0627\u0644\u0645\u062a\u0627\u062d\u060c \u0648\u064a\u0633\u0628\u0628 \u0636\u064a\u0642\u0627\u064b \u0641\u064a \u0627\u0644\u062a\u0646\u0641\u0633 \u0648\u0632\u064a\u0627\u062f\u0629 \u0646\u0628\u0636\u0627\u062a \u0627\u0644\u0642\u0644\u0628 \u0644\u062a\u0648\u0641\u064a\u0631 \u0627\u0644\u0623\u0643\u0633\u062c\u064a\u0646 \u0644\u0644\u062c\u0633\u0645.\n\u0645\u0631\u0636 \u0627\u0644\u062c\u0628\u0627\u0644 \u0627\u0644\u062d\u0627\u062f:\n \u064a\u0635\u064a\u0628 \u0627\u0644\u0628\u0639\u0636 \u0639\u0646\u062f \u0627\u0631\u062a\u0641\u0627\u0639 2500 \u0645\u062a\u0631 \u0641\u0623\u0643\u062b\u0631\u060c \u0648\u064a\u0634\u0645\u0644 \u0627\u0644\u062f\u0648\u0627\u0631\u060c \u0627\u0644\u0635\u062f\u0627\u0639\u060c \u0648\u0627\u0644\u062a\u0639\u0628.\n\u062a\u0645\u062f\u062f \u0627\u0644\u063a\u0627\u0632\u0627\u062a:\n \u0639\u0646\u062f \u0627\u0646\u062e\u0641\u0627\u0636 \u0627\u0644\u0636\u063a\u0637\u060c \u062a\u062a\u0645\u062f\u062f \u0627\u0644\u063a\u0627\u0632\u0627\u062a \u062f\u0627\u062e\u0644 \u0627\u0644\u062c\u0633\u0645\u060c \u0645\u0645\u0627 \u0642\u062f \u064a\u0633\u0628\u0628 \u0623\u0644\u0645\u0627\u064b \u0641\u064a \u0627\u0644\u0623\u0630\u0646 \u0648\u0627\u0644\u0628\u0637\u0646.\n\n\u062a\u0623\u062b\u064a\u0631\u0627\u062a \u0627\u0644\u062a\u0642\u0644\u0628\u0627\u062a (\u0627\u0644\u0636\u063a\u0637 \u0627\u0644\u0645\u0646\u062e\u0641\u0636/\u0627\u0644\u0645\u0631\u062a\u0641\u0639):\n\u0627\u0644\u0635\u062f\u0627\u0639 \u0627\u0644\u0646\u0635\u0641\u064a:\n \u064a\u0631\u062a\u0628\u0637 \u0627\u0646\u062e\u0641\u0627\u0636 \u0627\u0644\u0636\u063a\u0637 \u0627\u0644\u062c\u0648\u064a \u0628\u064a\u0646 6-10 \u0648\u062d\u062f\u0627\u062a \u0628\u0632\u064a\u0627\u062f\u0629 \u0627\u062d\u062a\u0645\u0627\u0644\u064a\u0629 \u062d\u062f\u0648\u062b \u0646\u0648\u0628\u0627\u062a \u0627\u0644\u0634\u0642\u064a\u0642\u0629.\n\u0622\u0644\u0627\u0645 \u0627\u0644\u0645\u0641\u0627\u0635\u0644 \u0648\u0627\u0644\u0623\u0646\u0633\u062c\u0629:\n \u0627\u0646\u062e\u0641\u0627\u0636 \u0627\u0644\u0636\u063a\u0637 \u0627\u0644\u062e\u0627\u0631\u062c\u064a \u064a\u0624\u062f\u064a \u0625\u0644\u0649 \u062a\u0645\u062f\u062f \u0637\u0641\u064a\u0641 \u0641\u064a \u0627\u0644\u0623\u0646\u0633\u062c\u0629 \u0648\u0627\u0644\u0639\u0636\u0644\u0627\u062a\u060c \u0645\u0645\u0627 \u064a\u0632\u064a\u062f \u0627\u0644\u0636\u063a\u0637 \u062d\u0648\u0644 \u0627\u0644\u0623\u0639\u0635\u0627\u0628 \u0648\u064a\u0641\u0627\u0642\u0645 \u0627\u0644\u0622\u0644\u0627\u0645 \u0627\u0644\u0645\u0632\u0645\u0646\u0629.\n\u0623\u0645\u0631\u0627\u0636 \u0627\u0644\u0642\u0644\u0628 \u0648\u0627\u0644\u0623\u0648\u0639\u064a\u0629 \u0627\u0644\u062f\u0645\u0648\u064a\u0629:\n \u062a\u0631\u062a\u0628\u0637 \u0627\u0644\u062a\u063a\u064a\u0631\u0627\u062a \u0627\u0644\u0645\u0641\u0627\u062c\u0626\u0629 \u0628\u0632\u064a\u0627\u062f\u0629 \u0627\u0644\u0623\u0632\u0645\u0627\u062a \u0627\u0644\u0642\u0644\u0628\u064a\u0629.\n \n\u062a\u0623\u062b\u064a\u0631\u0627\u062a \u0627\u0644\u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0634\u062f\u064a\u062f (\u0627\u0644\u0637\u064a\u0631\u0627\u0646):\n\u0639\u0646\u062f \u0627\u0644\u0627\u0631\u062a\u0641\u0627\u0639\u0627\u062a \u0627\u0644\u0639\u0627\u0644\u064a\u0629\u060c \u064a\u0643\u0648\u0646 \u0627\u0644\u0636\u063a\u0637 \u0645\u0646\u062e\u0641\u0636\u0627\u064b \u062c\u062f\u0627\u064b (\u062d\u0648\u0627\u0644\u064a 0.47 \u0636\u063a\u0637 \u062c\u0648\u064a \u0639\u0646\u062f 5950 \u0645\u062a\u0631\u0627\u064b)\u060c \u0648\u062a\u0635\u0628\u062d \u0627\u0644\u062d\u064a\u0627\u0629 \u0645\u0633\u062a\u062d\u064a\u0644\u0629 \u0641\u0648\u0642 8000 \u0645\u062a\u0631\u060c \u0644\u0630\u0627 \u064a\u062a\u0645 \u0636\u063a\u0637 \u0643\u0628\u0627\u0626\u0646 \u0627\u0644\u0637\u0627\u0626\u0631\u0627\u062a \u0644\u062a\u0634\u0627\u0628\u0647 \u0645\u0633\u062a\u0648\u0649 \u0633\u0637\u062d \u0627\u0644\u0628\u062d\u0631. \n\n\u0627\u0644\u0639\u0648\u0627\u0645\u0644 \u0627\u0644\u0645\u0624\u062b\u0631\u0629 \u0639\u0644\u0649 \u0627\u0644\u0636\u063a\u0637 \u0627\u0644\u062c\u0648\u064a:\n\u062f\u0631\u062c\u0629 \u0627\u0644\u062d\u0631\u0627\u0631\u0629:\n \u0627\u0644\u062d\u0631\u0627\u0631\u0629 \u0627\u0644\u0639\u0627\u0644\u064a\u0629 \u062a\u0642\u0644\u0644 \u0627\u0644\u0636\u063a\u0637 (\u062a\u062a\u0628\u0627\u0639\u062f \u0627\u0644\u062c\u0632\u064a\u0626\u0627\u062a)\u060c \u0648\u0627\u0644\u0628\u0631\u0648\u062f\u0629 \u062a\u0632\u064a\u062f \u0627\u0644\u0636\u063a\u0637.\n\u0627\u0644\u0631\u0637\u0648\u0628\u0629:\n \u064a\u062a\u0646\u0627\u0633\u0628 \u0627\u0644\u0636\u063a\u0637 \u0639\u0643\u0633\u064a\u0627\u064b \u0645\u0639 \u0627\u0644\u0631\u0637\u0648\u0628\u0629 (\u0632\u064a\u0627\u062f\u0629 \u0627\u0644\u0631\u0637\u0648\u0628\u0629 \u062a\u0639\u0646\u064a \u0627\u0646\u062e\u0641\u0627\u0636 \u0627\u0644\u0636\u063a\u0637).\n\u0627\u0644\u0627\u0631\u062a\u0641\u0627\u0639:\n \u064a\u0646\u062e\u0641\u0636 \u0627\u0644\u0636\u063a\u0637 \u0645\u0639 \u0632\u064a\u0627\u062f\u0629 \u0627\u0644\u0627\u0631\u062a\u0641\u0627\u0639.\n,\u0627\u0644\u0631\u064a\u0627\u062d:\n \u062a\u0624\u062b\u0631 \u0627\u0644\u0631\u064a\u0627\u062d \u0639\u0644\u0649 \u062a\u0648\u0632\u064a\u0639 \u0627\u0644\u0636\u063a\u0637 \u0627\u0644\u062c\u0648\u064a\u060c \u062d\u064a\u062b \u062a\u062a\u062c\u0647 \u0645\u0646 \u0645\u0646\u0627\u0637\u0642 \u0627\u0644\u0636\u063a\u0637 \u0627\u0644\u0639\u0627\u0644\u064a \u0625\u0644\u0649 \u0627\u0644\u0645\u0646\u062e\u0641\u0636.\n","\u0645\u0624\u0634\u0631 \u062c\u0648\u062f\u0629 \u0627\u0644\u0647\u0648\u0627\u0621 AQI \u064a\u0648\u0636\u062d \u0645\u0633\u062a\u0648\u0649 \u062a\u0644\u0648\u062b \u0627\u0644\u0647\u0648\u0627\u0621 \u0648\u062a\u0623\u062b\u064a\u0631\u0647 \u0627\u0644\u0645\u062d\u062a\u0645\u0644 \u0639\u0644\u0649 \u0627\u0644\u0635\u062d\u0629.\n\u0643\u0644\u0645\u0627 \u0627\u0631\u062a\u0641\u0639\u062a \u0627\u0644\u0642\u064a\u0645\u0629 \u0632\u0627\u062f\u062a \u0627\u062d\u062a\u0645\u0627\u0644\u064a\u0629 \u0627\u0644\u062a\u0623\u062b\u064a\u0631 \u0639\u0644\u0649 \u0627\u0644\u0623\u0634\u062e\u0627\u0635 \u0627\u0644\u062d\u0633\u0627\u0633\u064a\u0646 \u0645\u062b\u0644 \u0645\u0631\u0636\u0649 \u0627\u0644\u0631\u0628\u0648 \u0648\u0627\u0644\u062d\u0633\u0627\u0633\u064a\u0629.\n\n0 - 50: \u062c\u064a\u062f.\n51 - 100: \u0645\u0642\u0628\u0648\u0644.\n101 - 150: \u063a\u064a\u0631 \u0635\u062d\u064a \u0644\u0644\u062d\u0633\u0627\u0633\u064a\u0646.\n151 - 200: \u063a\u064a\u0631 \u0635\u062d\u064a.\n201 - 300: \u0633\u064a\u0626 \u062c\u062f\u0627\u064b.\n301+: \u062e\u0637\u0631.\n","\u0647\u0630\u0627 \u0627\u0644\u0645\u0624\u0634\u0631 \u062a\u0642\u062f\u064a\u0631\u064a \u064a\u0639\u062a\u0645\u062f \u0639\u0644\u0649 \u0627\u0644\u0636\u063a\u0637 \u0627\u0644\u062c\u0648\u064a \u0648\u0627\u0644\u0631\u0637\u0648\u0628\u0629 \u0648\u062f\u0631\u062c\u0629 \u0627\u0644\u062d\u0631\u0627\u0631\u0629.\n\u0642\u062f \u062a\u0632\u062f\u0627\u062f \u0622\u0644\u0627\u0645 \u0627\u0644\u0645\u0641\u0627\u0635\u0644 \u0639\u0646\u062f \u0627\u0646\u062e\u0641\u0627\u0636 \u0627\u0644\u0636\u063a\u0637 \u0648\u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0631\u0637\u0648\u0628\u0629 \u0623\u0648 \u062d\u062f\u0648\u062b \u062a\u063a\u064a\u0631\u0627\u062a \u062c\u0648\u064a\u0629 \u0645\u0641\u0627\u062c\u0626\u0629.\n","\u0647\u0630\u0627 \u0627\u0644\u0645\u0624\u0634\u0631 \u062a\u0642\u062f\u064a\u0631\u064a \u064a\u0639\u062a\u0645\u062f \u0639\u0644\u0649 \u0627\u0644\u0636\u063a\u0637 \u0627\u0644\u062c\u0648\u064a \u0648\u0627\u0644\u0631\u0637\u0648\u0628\u0629 \u0648\u0627\u0644\u0631\u064a\u0627\u062d.\n\u062a\u063a\u064a\u0631\u0627\u062a \u0627\u0644\u0636\u063a\u0637 \u0648\u0627\u0644\u0647\u0648\u0627\u0621 \u0627\u0644\u062c\u0627\u0641 \u0623\u0648 \u0627\u0644\u063a\u0628\u0627\u0631 \u0642\u062f \u062a\u0632\u064a\u062f \u0645\u0646 \u0627\u0644\u0625\u062d\u0633\u0627\u0633 \u0628\u0636\u063a\u0637 \u0627\u0644\u062c\u064a\u0648\u0628 \u0627\u0644\u0623\u0646\u0641\u064a\u0629.\n","\u0647\u0630\u0627 \u0627\u0644\u0645\u0624\u0634\u0631 \u062a\u0642\u062f\u064a\u0631\u064a \u064a\u0639\u062a\u0645\u062f \u0639\u0644\u0649 \u062f\u0631\u062c\u0629 \u0627\u0644\u062d\u0631\u0627\u0631\u0629 \u0648\u0627\u0644\u0631\u0637\u0648\u0628\u0629.\n\u0627\u0644\u0623\u062c\u0648\u0627\u0621 \u0627\u0644\u0628\u0627\u0631\u062f\u0629 \u0648\u0627\u0644\u0631\u0637\u0628\u0629 \u0642\u062f \u062a\u0632\u064a\u062f \u0642\u0627\u0628\u0644\u064a\u0629 \u0627\u0646\u062a\u0634\u0627\u0631 \u0646\u0632\u0644\u0627\u062a \u0627\u0644\u0628\u0631\u062f \u0648\u0627\u0644\u0625\u0646\u0641\u0644\u0648\u0646\u0632\u0627.\n","\u0647\u0630\u0627 \u0627\u0644\u0645\u0624\u0634\u0631 \u062a\u0642\u062f\u064a\u0631\u064a \u064a\u0639\u062a\u0645\u062f \u0639\u0644\u0649 \u0627\u0644\u0636\u063a\u0637 \u0627\u0644\u062c\u0648\u064a \u0648\u0627\u0644\u0631\u064a\u0627\u062d.\n\u0627\u0644\u062a\u063a\u064a\u0631\u0627\u062a \u0627\u0644\u0633\u0631\u064a\u0639\u0629 \u0641\u064a \u0627\u0644\u0636\u063a\u0637 \u0627\u0644\u062c\u0648\u064a \u0642\u062f \u062a\u0631\u062a\u0628\u0637 \u0628\u0632\u064a\u0627\u062f\u0629 \u0627\u062d\u062a\u0645\u0627\u0644\u064a\u0629 \u0627\u0644\u0635\u062f\u0627\u0639 \u0627\u0644\u0646\u0635\u0641\u064a \u0644\u062f\u0649 \u0628\u0639\u0636 \u0627\u0644\u0623\u0634\u062e\u0627\u0635.\n","\u0647\u0630\u0627 \u0627\u0644\u0645\u0624\u0634\u0631 \u062a\u0642\u062f\u064a\u0631\u064a \u064a\u0639\u062a\u0645\u062f \u0639\u0644\u0649 \u0645\u062f\u0649 \u0627\u0644\u0631\u0624\u064a\u0629 \u0648\u0627\u0644\u0631\u064a\u0627\u062d \u0648\u0627\u0644\u0631\u0637\u0648\u0628\u0629.\n\u0627\u0644\u063a\u0628\u0627\u0631 \u0648\u0636\u0639\u0641 \u0627\u0644\u0631\u0624\u064a\u0629 \u0648\u0627\u0644\u0631\u0637\u0648\u0628\u0629 \u0627\u0644\u0639\u0627\u0644\u064a\u0629 \u0642\u062f \u062a\u0632\u064a\u062f \u0645\u0646 \u062a\u0647\u064a\u062c \u0627\u0644\u062c\u0647\u0627\u0632 \u0627\u0644\u062a\u0646\u0641\u0633\u064a \u0644\u062f\u0649 \u0645\u0631\u0636\u0649 \u0627\u0644\u0631\u0628\u0648.\n","\u0647\u0630\u0627 \u0627\u0644\u0645\u0624\u0634\u0631 \u062a\u0642\u062f\u064a\u0631\u064a \u064a\u0639\u062a\u0645\u062f \u0639\u0644\u0649 \u062f\u0631\u062c\u0629 \u0627\u0644\u062d\u0631\u0627\u0631\u0629 \u0648\u0627\u0644\u0631\u0637\u0648\u0628\u0629 \u0648\u0633\u0631\u0639\u0629 \u0627\u0644\u0631\u064a\u0627\u062d.\n\u064a\u0632\u062f\u0627\u062f \u0646\u0634\u0627\u0637 \u0627\u0644\u0628\u0639\u0648\u0636 \u0639\u0627\u062f\u0629 \u0641\u064a \u0627\u0644\u0623\u062c\u0648\u0627\u0621 \u0627\u0644\u062f\u0627\u0641\u0626\u0629 \u0648\u0627\u0644\u0631\u0637\u0628\u0629 \u0645\u0639 \u0636\u0639\u0641 \u0627\u0644\u0631\u064a\u0627\u062d.\n"],t.w)
